<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Personal Expense Tracker</title>
  <style>
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: Arial, sans-serif;
      background: #f4f6f8;
      color: #17212b;
    }
    main {
      max-width: 760px;
      margin: 32px auto;
      padding: 24px;
      background: white;
      border-radius: 10px;
      box-shadow: 0 2px 12px rgba(0,0,0,.1);
    }
    h1, h2 { margin-top: 0; }
    form, .filters {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(145px, 1fr));
      gap: 12px;
      margin-bottom: 18px;
    }
    label {
      display: flex;
      flex-direction: column;
      gap: 5px;
      font-size: 14px;
      font-weight: bold;
    }
    input, select, button {
      padding: 9px;
      border: 1px solid #b8c2cc;
      border-radius: 5px;
      font: inherit;
    }
    button {
      cursor: pointer;
      background: #2563eb;
      color: white;
      border: 0;
      align-self: end;
    }
    button:hover { background: #1d4ed8; }
    #form-error {
      min-height: 20px;
      margin: -8px 0 14px;
      color: #b91c1c;
      font-size: 14px;
    }
    .summary {
      padding: 14px;
      background: #eef4ff;
      border-radius: 6px;
      margin-bottom: 18px;
    }
    #total {
      font-size: 24px;
      font-weight: bold;
    }
    #category-summary {
      display: flex;
      flex-wrap: wrap;
      gap: 10px 18px;
      margin-top: 10px;
      font-size: 14px;
    }
    .expense {
      display: grid;
      grid-template-columns: 100px 115px 120px 1fr auto;
      gap: 10px;
      align-items: center;
      padding: 12px 0;
      border-bottom: 1px solid #e1e6eb;
    }
    .expense-note { color: #52606d; overflow-wrap: anywhere; }
    .exp-del { background: #dc2626; padding: 7px 10px; }
    .exp-del:hover { background: #b91c1c; }
    #expenses:empty::after {
      content: "No expenses yet.";
      display: block;
      color: #667085;
      padding: 14px 0;
    }
    @media (max-width: 580px) {
      .expense { grid-template-columns: 1fr 1fr auto; }
      .expense-note { grid-column: 1 / -1; }
    }
  </style>
</head>
<body>
  <main>
    <h1>Expense Tracker</h1>

    <form id="expense-form">
      <label>Amount
        <input id="amount" type="number" min="0" step="0.01" placeholder="0.00">
      </label>
      <label>Category
        <select id="category">
          <option value="groceries">groceries</option>
          <option value="transport">transport</option>
          <option value="bills">bills</option>
          <option value="fun">fun</option>
        </select>
      </label>
      <label>Date
        <input id="date" type="date">
      </label>
      <label>Note
        <input id="note" type="text" placeholder="Optional">
      </label>
      <button id="add-expense" type="submit">Add expense</button>
    </form>
    <div id="form-error" aria-live="polite"></div>

    <h2>Filters</h2>
    <div class="filters">
      <label>Category
        <select id="filter-category">
          <option value="all">all</option>
          <option value="groceries">groceries</option>
          <option value="transport">transport</option>
          <option value="bills">bills</option>
          <option value="fun">fun</option>
        </select>
      </label>
      <label>From
        <input id="filter-from" type="date">
      </label>
      <label>To
        <input id="filter-to" type="date">
      </label>
    </div>

    <section class="summary" aria-live="polite">
      Total: <span id="total">0.00</span>
      <div id="category-summary">
        <span class="cat-total" data-cat="groceries">groceries: 0.00</span>
        <span class="cat-total" data-cat="transport">transport: 0.00</span>
        <span class="cat-total" data-cat="bills">bills: 0.00</span>
        <span class="cat-total" data-cat="fun">fun: 0.00</span>
      </div>
    </section>

    <h2>Expenses</h2>
    <div id="expenses"></div>
  </main>

  <script>
    (function () {
      const categories = ["groceries", "transport", "bills", "fun"];
      const storageKey = "personal-expense-tracker-expenses";
      const form = document.getElementById("expense-form");
      const amountInput = document.getElementById("amount");
      const categoryInput = document.getElementById("category");
      const dateInput = document.getElementById("date");
      const noteInput = document.getElementById("note");
      const error = document.getElementById("form-error");
      const list = document.getElementById("expenses");
      const total = document.getElementById("total");
      const filterCategory = document.getElementById("filter-category");
      const filterFrom = document.getElementById("filter-from");
      const filterTo = document.getElementById("filter-to");

      let expenses = loadExpenses();

      function loadExpenses() {
        try {
          const saved = JSON.parse(localStorage.getItem(storageKey));
          return Array.isArray(saved) ? saved.filter(function (item) {
            return item && Number(item.amount) > 0 && categories.includes(item.category) && item.date;
          }) : [];
        } catch (_) {
          return [];
        }
      }

      function saveExpenses() {
        localStorage.setItem(storageKey, JSON.stringify(expenses));
      }

      function matchesFilters(expense) {
        const category = filterCategory.value;
        const from = filterFrom.value;
        const to = filterTo.value;
        return (category === "all" || expense.category === category) &&
          (!from || expense.date >= from) &&
          (!to || expense.date <= to);
      }

      function render() {
        list.innerHTML = "";
        const visible = expenses
          .filter(matchesFilters)
          .sort(function (a, b) { return b.createdAt - a.createdAt; });

        const sums = { groceries: 0, transport: 0, bills: 0, fun: 0 };
        let visibleTotal = 0;

        visible.forEach(function (expense) {
          visibleTotal += Number(expense.amount);
          sums[expense.category] += Number(expense.amount);

          const row = document.createElement("div");
          row.className = "expense";

          const amount = document.createElement("strong");
          amount.textContent = Number(expense.amount).toFixed(2);

          const category = document.createElement("span");
          category.textContent = expense.category;

          const date = document.createElement("span");
          date.textContent = expense.date;

          const note = document.createElement("span");
          note.className = "expense-note";
          note.textContent = expense.note || "";

          const remove = document.createElement("button");
          remove.className = "exp-del";
          remove.type = "button";
          remove.textContent = "Delete";
          remove.addEventListener("click", function () {
            expenses = expenses.filter(function (item) {
              return item.id !== expense.id;
            });
            saveExpenses();
            render();
          });

          row.append(amount, category, date, note, remove);
          list.appendChild(row);
        });

        total.textContent = visibleTotal.toFixed(2);
        categories.forEach(function (category) {
          const element = document.querySelector('.cat-total[data-cat="' + category + '"]');
          element.textContent = category + ": " + sums[category].toFixed(2);
        });
      }

      form.addEventListener("submit", function (event) {
        event.preventDefault();

        const rawAmount = amountInput.value.trim();
        const amount = Number(rawAmount);
        const date = dateInput.value;

        if (!rawAmount || !Number.isFinite(amount) || amount <= 0 || !date) {
          error.textContent = "Enter a valid positive amount and date.";
          return;
        }

        error.textContent = "";
        expenses.push({
          id: String(Date.now()) + "-" + Math.random().toString(16).slice(2),
          amount: amount,
          category: categoryInput.value,
          date: date,
          note: noteInput.value.trim(),
          createdAt: Date.now()
        });

        saveExpenses();
        amountInput.value = "";
        render();
      });

      [filterCategory, filterFrom, filterTo].forEach(function (control) {
        control.addEventListener("change", render);
        control.addEventListener("input", render);
      });

      render();
    })();
  </script>
</body>
</html>
